using System;using System.IO;using System.Linq;using System.Threading;using System.Threading.Tasks;using V15Voice;
public static class NativeGpuTests {
 static int count;static void Check(bool x,string name){if(!x)throw new Exception("FAIL "+name);Console.WriteLine("PASS "+name);count++;}
 static void Reject(Action a,string name){try{a();}catch(Exception e){if(e.Message.StartsWith("FAIL"))throw;Check(true,name);return;}throw new Exception("FAIL "+name);}
 public static void Main(string[] args){string root=args[0],output=Path.Combine(root,"out.wav"),log=Path.Combine(root,"calls");
  foreach(var k in new[]{EngineKind.Kokoro,EngineKind.LibriTTS,EngineKind.Kitten,EngineKind.Piper}){using(var e=new KokoroEngine{Root=root,Kind=k,DeviceMode="gpu"}){e.Generate("Hello.",1,output);Check(e.DeviceInfo.Contains("CUDA")&&File.ReadAllLines(log).Last().StartsWith("gpu --provider=cuda"),k+" dispatches CUDA and confirms a valid WAV");}}
  using(var e=new KokoroEngine{Root=root,DeviceMode="cpu"}){e.Generate("Hello.",1,output);Check(e.DeviceInfo.StartsWith("CPU")&&File.ReadAllLines(log).Last().StartsWith("cpu --provider=cpu"),"Explicit CPU uses original executable and reports CPU");}
  File.WriteAllText(Path.Combine(root,"fallback"),"1");using(var e=new KokoroEngine{Root=root,DeviceMode="auto"}){int before=File.ReadAllLines(log).Length;e.Generate("Hello.",1,output);Check(File.ReadAllLines(log).Length==before+2&&e.DeviceInfo.Contains("dự phòng"),"Auto detects silent CPU fallback and reruns once on original CPU engine");before=File.ReadAllLines(log).Length;e.Generate("Next.",1,output);Check(File.ReadAllLines(log).Length==before+1&&File.ReadAllLines(log).Last().StartsWith("cpu"),"Following cue stays on working CPU after GPU failure");}
  using(var e=new KokoroEngine{Root=root,DeviceMode="gpu"})Reject(()=>e.Generate("Hello.",1,output),"Required GPU rejects silent CPU fallback");Check(!File.Exists(output),"Rejected GPU result is removed");File.Delete(Path.Combine(root,"fallback"));
  File.WriteAllText(Path.Combine(root,"error"),"1");using(var e=new KokoroEngine{Root=root,DeviceMode="auto"}){e.Generate("Hello.",1,output);Check(e.DeviceInfo.Contains("dự phòng"),"Nonzero GPU process error recovers with fresh CPU process");}File.Delete(Path.Combine(root,"error"));
  File.Move(NativeGpu.Executable(root),NativeGpu.Executable(root)+".disabled");using(var e=new KokoroEngine{Root=root,DeviceMode="gpu"})Reject(()=>e.Generate("Hello.",1,output),"Required GPU explains missing addon");using(var e=new KokoroEngine{Root=root,DeviceMode="auto"}){e.Generate("Hello.",1,output);Check(e.DeviceInfo.Contains("Chưa có gói"),"Auto reports reason for CPU when addon is absent");}File.Move(NativeGpu.Executable(root)+".disabled",NativeGpu.Executable(root));
  File.WriteAllText(Path.Combine(root,"delay"),"1");using(var e=new KokoroEngine{Root=root,DeviceMode="auto"}){int before=File.ReadAllLines(log).Length;var task=Task.Run(()=>{try{e.Generate("Hello.",1,output);return false;}catch(OperationCanceledException){return true;}});Thread.Sleep(250);e.Cancel();Check(task.Result&&File.ReadAllLines(log).Length==before+1,"Cancel stops active process without CPU retry");}File.Delete(Path.Combine(root,"delay"));
  Check(NativeGpu.FellBack("Fallback to cpu!")&&NativeGpu.FellBack("Failed to create CUDAExecutionProvider")&&!NativeGpu.FellBack("CPU nodes placed for shape operations"),"Recognizes unavailable CUDA without mistaking partial CPU graph nodes for full fallback");
  Console.WriteLine("TOTAL NATIVE GPU "+count+" passed.");
 }
}
